<script lang="ts">
  // XLR8 logo as inline SVG in currentColor: follows light and dark mode. Shapes from
  // lib/brand.ts (generated by tooling/brand.mjs from the original under app/public/brand/).
  import { BRAND } from '../lib/brand.ts';

  let { kind = 'mark', height = 20, label = 'XLR8' }: { kind?: 'mark' | 'word' | 'full'; height?: number; label?: string | null } = $props();
  const shape = $derived(BRAND[kind]);
  const d = $derived(kind === 'full' ? BRAND.mark.d + BRAND.word.d : BRAND[kind].d);
</script>

<svg
  class="logo logo-{kind}"
  viewBox={shape.viewBox}
  width={Math.round(height * shape.ratio * 100) / 100}
  {height}
  fill="currentColor"
  fill-rule="evenodd"
  role={label ? 'img' : undefined}
  aria-label={label}
  aria-hidden={label ? undefined : 'true'}
  focusable="false"
><path {d} /></svg>
